/**
 *
 * Tabs component is used to select a boolean value.
 *
 * [Live Demo](https://www.primereact.org/tabs/)
 *
 * @module TabsRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseTabsChangeEvent, UseTabsExposes, UseTabsProps, UseTabsState } from '@primereact/types/headless/tabs';
import type { BaseComponentProps, PassThroughType } from '../..';
/**
 * Defines passthrough(pt) options type in Tabs component.
 */
export type TabsRootPassThroughType<E> = PassThroughType<TabsRootInstance, E>;
/**
 * Defines passthrough(pt) options of Tabs component.
 */
export interface TabsRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TabsRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the list's DOM element.
     */
    list?: TabsRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the content's DOM element.
     */
    content?: TabsRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the tab's DOM element.
     */
    tab?: TabsRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the indicator's DOM element.
     */
    indicator?: TabsRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the panels' DOM element.
     */
    panels?: TabsRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the panel's DOM element.
     */
    panel?: TabsRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the prev button's DOM element.
     */
    prev?: TabsRootPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
    /**
     * Used to pass attributes to the next button's DOM element.
     */
    next?: TabsRootPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
/**
 * Defines valid properties in Tabs component.
 */
export interface TabsRootProps extends BaseComponentProps<TabsRootInstance, UseTabsProps, TabsRootPassThrough> {
    /**
     * When enabled, hidden tabs are not rendered at all. Defaults to false that hides tabs with css.
     * @default false
     */
    lazy?: boolean | undefined;
}
/**
 * Defines valid state in Tabs component.
 */
export interface TabsRootState extends UseTabsState {
}
/**
 * Defines the methods and properties exposed by Tabs component.
 */
export interface TabsRootExposes extends UseTabsExposes {
}
/**
 * Event fired when the tabs's value changes.
 * @extends UseTabsChangeEvent
 */
export interface TabsRootChangeEvent extends UseTabsChangeEvent {
}
/**
 * Instance of Tabs component.
 */
export type TabsRootInstance = ComponentInstance<TabsRootProps, TabsRootState, TabsRootExposes>;
